// INPUT PARSER - Project 3 Competitor Monitoring
// Extracts category + optional focus keyword from chat input.
// Products for each retailer are pulled by category from the program's data server.

const input = $input.first().json.chatInput || '';

const categories = [
  { key: 'area_rug',       displayName: 'Area Rug' },
  { key: 'outdoor_rug',    displayName: 'Outdoor Rug' },
  { key: 'hallway_runner', displayName: 'Hallway Runner' },
  { key: 'shag_rug',       displayName: 'Shag Rug' },
];
const byKey = Object.fromEntries(categories.map(c => [c.key, c]));

// Normalise: "outdoor_rug", "Outdoor-Rugs" and "outdoor rugs" all become "outdoor rugs".
const lowerInput = input.toLowerCase().replace(/focus\s*:[^\n]*/i, ' ').replace(/[_\-]+/g, ' ').replace(/\s+/g, ' ').trim();

// Most specific words first, so "outdoor area rug" resolves to outdoor_rug.
const rules = [
  [/\b(outdoor|patio|deck)\b/, 'outdoor_rug'],
  [/\b(hallway|hall|runners?)\b/, 'hallway_runner'],
  [/\b(shag|shaggy)\b/, 'shag_rug'],
  [/\barea\b/, 'area_rug'],
];
let detectedCategory = null;
for (const [re, key] of rules) {
  if (re.test(lowerInput)) { detectedCategory = byKey[key]; break; }
}

if (!detectedCategory) {
  throw new Error(`Could not tell which rug category to analyze. Type one of: area rug, outdoor rug, hallway runner, shag rug (optionally add "focus: washable"). You typed: "${input}"`);
}

// Optional focus keyword (e.g. "focus: washable")
const focusMatch = input.match(/focus\s*:\s*([^\n]+)/i);
const focus = focusMatch ? focusMatch[1].trim() : '';

const hasCategory = !!detectedCategory;
const categoryKey = detectedCategory ? detectedCategory.key : null;
const categoryDisplayName = detectedCategory ? detectedCategory.displayName : null;

return [{
  json: {
    category: categoryKey,
    categoryKey,
    categoryDisplayName,
    focus,
    hasValidInput: hasCategory,
    errorReason: hasCategory ? null : 'no_category',
    originalInput: input,
    parsedAt: new Date().toISOString(),
  }
}];

// Reshape FastAPI response to the legacy shape that downstream consumers expect.
const r = $input.first().json;
const products = r.products || [];
return [{
  json: {
    wayfair_products: products.map(p => ({
      url: p.url,
      name: p.name,
      price: p.price,
      details: p.details || [],
      pattern: p.pattern || '',
      image_url: p.image_url || '',
      rating: p.rating || '',
      review_count: p.review_count || '',
      scraped_at: r.scraped_at || new Date().toISOString(),
    })),
    totalWayfair: products.length,
    totalProducts: products.length,
    scrapedAt: r.scraped_at || new Date().toISOString(),
  },
}];

// Reshape FastAPI response to the legacy shape that downstream consumers expect.
const r = $input.first().json;
const products = r.products || [];
return [{
  json: {
    amazonProducts: products.map(p => ({
      url: p.url,
      name: p.name,
      price: p.price,
      details: p.details || [],
      pattern: p.pattern || '',
      image_url: p.image_url || '',
      rating: p.rating || '',
      review_count: p.review_count || '',
      scraped_at: r.scraped_at || new Date().toISOString(),
    })),
    totalAmazonProducts: products.length,
    totalProducts: products.length,
    scrapedAt: r.scraped_at || new Date().toISOString(),
  },
}];

// Reshape FastAPI response to the legacy shape that downstream consumers expect.
const r = $input.first().json;
const products = r.products || [];
return [{
  json: {
    walmartProducts: products.map(p => ({
      url: p.url,
      name: p.name,
      price: p.price,
      details: p.details || [],
      pattern: p.pattern || '',
      image_url: p.image_url || '',
      rating: p.rating || '',
      review_count: p.review_count || '',
      scraped_at: r.scraped_at || new Date().toISOString(),
    })),
    totalWalmartProducts: products.length,
    totalProducts: products.length,
    scrapedAt: r.scraped_at || new Date().toISOString(),
  },
}];

// SCOPE GENERATOR - No AI, just JavaScript
// Generates Section 2: Scope of Research

const wayfairData = $('Reshape Wayfair Response').first().json;
const amazonData = $('Reshape Amazon Response').first().json;
let walmartData = {};
try { walmartData = $('Reshape Walmart Response').first().json || {}; } catch(e) {}
const inputData = $('Input Parser').first().json;

// ---- GUARD: if no retailer returned products, stop with the reason instead of writing a report from nothing ----
const fetchError = n => {
  try {
    const j = $(n).first().json;
    return j.error ? (typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error))) : '';
  } catch (e) { return ''; }
};
if (!(wayfairData.wayfair_products?.length) && !(amazonData.amazonProducts?.length) && !(walmartData.walmartProducts?.length)) {
  const errs = ['Fetch Wayfair Products', 'Fetch Amazon Products', 'Fetch Walmart Products']
    .map(n => [n, fetchError(n)]).filter(x => x[1]).map(x => `${x[0]}: ${String(x[1]).slice(0, 200)}`).join(' | ');
  throw new Error(`No products were returned for category "${inputData.categoryKey}". ${errs || 'The API answered but the product lists were empty.'} Check that http://34.196.186.128:8000/api/health is reachable and that GET /api/products/<retailer>?category=${inputData.categoryKey} returns products.`);
}

const category = inputData.categoryDisplayName || 'Rugs';
const amazonProductCount = amazonData.amazonProducts?.length || amazonData.totalProducts || 0;
const wayfairProductCount = wayfairData.wayfair_products?.length || 0;
const walmartProductCount = walmartData.walmartProducts?.length || walmartData.totalProducts || 0;

const scopeHtml = `
<section class="scope-section">
  <h2>Scope of Research</h2>
  <div class="scope-grid">
    <div class="scope-card">
      <h4>Category Analyzed</h4>
      <p class="scope-value">${category}</p>
    </div>
    <div class="scope-card">
      <h4>Competitors Reviewed</h4>
      <ul>
        <li><strong>Amazon</strong> - ${amazonProductCount} products analyzed</li>
        <li><strong>Walmart</strong> - ${walmartProductCount} products analyzed</li>
        <li><strong>Wayfair</strong> - ${wayfairProductCount} products (baseline)</li>
      </ul>
    </div>
    <div class="scope-card">
      <h4>Data Sources</h4>
      <ul>
        <li>Product listings & pricing</li>
        <li>Customer reviews & ratings</li>
        <li>Product features & specifications</li>
      </ul>
    </div>
    <div class="scope-card">
      <h4>Report Generated</h4>
      <p class="scope-value">${new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}</p>
    </div>
  </div>
</section>
`;

return [{
  json: {
    section: 'scope',
    html: scopeHtml,
    metadata: {
      category,
      amazonProductCount,
      walmartProductCount,
      wayfairProductCount,
      generatedAt: new Date().toISOString()
    }
  }
}];

// AMAZON ANALYSIS GENERATOR (no LLM) - drop-in replacement for the HTTP node of the same name.
// Builds the whole "Competitor Analysis" section from the raw product arrays, so the markup is always
// balanced and product names are real names (no [brackets] or "..." from a model).
// Output shape matches what HTML Assembler / Recommendations Generator read: json.choices[0].message.content
// API formats: price "NN.NN", rating "X.X out of 5 stars", review_count "3902"; any of them may be "".

const safe = (name, key) => { try { return $(name).first().json[key] || []; } catch (e) { return []; } };
const amazon  = safe('Reshape Amazon Response', 'amazonProducts');
const walmart = safe('Reshape Walmart Response', 'walmartProducts');

// ---------- helpers ----------
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const escUrl = u => String(u ?? '').trim().replace(/"/g, '%22').replace(/</g, '%3C').replace(/>/g, '%3E');
const parseNum = v => { const m = String(v ?? '').replace(/,/g, '').match(/\d+(?:\.\d+)?/); return m ? parseFloat(m[0]) : NaN; };
const parseRating = v => { const m = String(v ?? '').match(/(\d+(?:\.\d+)?)\s*out of\s*5/i); return m ? parseFloat(m[1]) : parseNum(v); };
const parseCount = v => { const m = String(v ?? '').replace(/,/g, '').toLowerCase().match(/(\d+(?:\.\d+)?)\s*(k)?/); return m ? Math.round(parseFloat(m[1]) * (m[2] ? 1000 : 1)) : NaN; };
const ok = Number.isFinite;
const mean = a => a.reduce((s, x) => s + x, 0) / a.length;
const money = x => ok(x) ? '$' + x.toFixed(2) : 'N/A';

// Clean display name: strip stray brackets and a trailing ellipsis, collapse whitespace, cut at a word boundary. No ellipsis; full name goes in the tooltip.
const cleanName = n => String(n ?? '').replace(/[\[\]]/g, '').replace(/\s+/g, ' ').replace(/(?:\.{2,}|\u2026)\s*$/, '').trim();
const shortName = n => {
  const full = cleanName(n);
  if (full.length <= 70) return full;
  const brk = full.search(/\s[-–|]\s|,\s/);                 // first natural break (" - ", " | ", ", ")
  if (brk >= 25 && brk <= 70) return full.slice(0, brk);
  const cut = full.slice(0, 70);
  return cut.slice(0, Math.max(cut.lastIndexOf(' '), 40)).replace(/[\s,;:|\-–]+$/, '');
};
const link = p => {
  const name = shortName(p.name) || 'Unnamed product';
  const tip = esc(cleanName(p.name));
  return p.url ? `<a href="${escUrl(p.url)}" target="_blank" title="${tip}">${esc(name)}</a>` : `<span title="${tip}">${esc(name)}</span>`;
};

// Sizes like 5'x8', 5'3 x 7', 6'7" x 9'6", 8x10, 5 x 8 ft  (best effort, from name + feature bullets)
const sizeDim = `\\d{1,2}(?:\\.\\d+)?(?:\\s*(?:ft\\.?|feet|['′])\\s*(?:\\d{1,2}(?:\\.\\d+)?\\s*(?:"|in\\.?|″)?)?)?`;
const sizeRe = new RegExp(`(?<![\\d.])${sizeDim}\\s*[x×]\\s*${sizeDim}(?!\\d)`, 'i');
const sizeOf = p => {
  const m = (cleanName(p.name) + ' ' + (p.details || []).join(' ')).match(sizeRe);
  return m ? m[0].replace(/\s+/g, ' ').trim() : '';
};

const featureDefs = [
  ['Waterproof / Water Resistant', /water[\s-]?(?:proof|resistant)/i],
  ['UV / Fade Resistant', /\b(?:uv|fade)[\s-]?(?:resistant|proof|protected)|fade[\s-]?resistant/i],
  ['Stain Resistant', /stain[\s-]?(?:resistant|proof)/i],
  ['Easy to Clean', /easy[\s-]?(?:to[\s-]?)?clean|machine[\s-]?wash|hose|wipe/i],
  ['Pet Friendly', /pet[\s-]?friendly|pet[\s-]?safe/i],
  ['Non-Slip', /non[\s-]?(?:slip|skid)|slip[\s-]?resistant/i],
  ['Reversible', /reversible/i],
  ['Indoor / Outdoor Use', /indoor[\s\/&,-]*(?:and\s*)?outdoor|outdoor[\s\/&,-]*(?:and\s*)?indoor/i],
  ['Lightweight', /lightweight/i],
  ['Durable / Weather Resistant', /durab|weather[\s-]?(?:resistant|proof)/i],
];

// ---------- per-platform stats ----------
const stats = items => {
  const prices = items.map(p => parseNum(p.price)).filter(x => ok(x) && x > 0);
  const ratings = items.map(p => parseRating(p.rating)).filter(x => ok(x) && x > 0 && x <= 5);
  const patterns = {};
  items.forEach(p => { const k = String(p.pattern || '').trim(); if (k) patterns[k.toLowerCase()] = { name: k, n: (patterns[k.toLowerCase()]?.n || 0) + 1 }; });
  const feats = featureDefs.map(([label, re]) => [label, items.filter(p => re.test(cleanName(p.name) + ' ' + (p.details || []).join(' '))).length])
    .filter(f => f[1] > 0).sort((a, b) => b[1] - a[1]);
  return {
    n: items.length, nPriced: prices.length, nRated: ratings.length,
    min: prices.length ? Math.min(...prices) : NaN, max: prices.length ? Math.max(...prices) : NaN,
    avgPrice: prices.length ? mean(prices) : NaN, avgRating: ratings.length ? mean(ratings) : NaN,
    patterns: Object.values(patterns).sort((a, b) => b.n - a.n), feats,
  };
};
const sa = stats(amazon), sw = stats(walmart);

// Top 3 by review-adjusted rating (Bayesian average, prior = 10 reviews at the platform's mean rating)
const top3 = (items, s) => {
  const C = ok(s.avgRating) ? s.avgRating : 0, m = 10;
  const scored = items.map(p => {
    const R = parseRating(p.rating), v = parseCount(p.review_count);
    return { p, score: ok(R) && R > 0 ? ((ok(v) ? v : 0) / ((ok(v) ? v : 0) + m)) * R + (m / ((ok(v) ? v : 0) + m)) * C : -1 };
  });
  return scored.sort((a, b) => b.score - a.score).slice(0, 3).map(x => x.p);
};
const ratingCell = p => {
  const R = parseRating(p.rating), v = parseCount(p.review_count);
  return ok(R) && R > 0 ? `${R.toFixed(1)}${ok(v) ? ` (${v})` : ''}` : '—';
};
const statCards = (s, withRating) => `
        <div class="stat-card"><span class="stat-value">${s.n}</span><span class="stat-label">Products Analyzed</span></div>
        <div class="stat-card"><span class="stat-value">${ok(s.min) ? money(s.min) + ' - ' + money(s.max) : 'N/A'}</span><span class="stat-label">Price Range</span></div>` +
  (withRating ? `
        <div class="stat-card"><span class="stat-value">${ok(s.avgRating) ? s.avgRating.toFixed(1) + '/5' : 'N/A'}</span><span class="stat-label">Avg Rating</span></div>` : '');

const amazonRows = top3(amazon, sa).map(p => `
            <tr><td>${link(p)}</td><td>${p.price ? money(parseNum(p.price)) : '—'}</td><td>${ratingCell(p)}</td></tr>`).join('');
const walmartRows = top3(walmart, sw).map(p => `
            <tr><td>${link(p)}</td><td>${p.price ? money(parseNum(p.price)) : '—'}</td><td>${esc(sizeOf(p) || '—')}</td></tr>`).join('');

const minCommon = Math.max(2, Math.ceil(sa.n * 0.25));
const featureItems = sa.feats.filter(f => f[1] >= minCommon).slice(0, 5).map(([l, n]) => `<li>${l} <small>(${n} of ${sa.n} products)</small></li>`).join('')
  || '<li>No common features found in the product details</li>';

// Size / color variety (Walmart)
const sizes = [...new Set(walmart.map(sizeOf).filter(Boolean))];
const sizesLine = sizes.length
  ? `Found for ${walmart.filter(sizeOf).length} of ${sw.n} products; examples: ${sizes.slice(0, 5).map(esc).join(', ')}`
  : 'No sizes could be read from the product data';
const patternsLine = sw.patterns.length
  ? `${sw.patterns.length} distinct patterns/variants; most common: ${sw.patterns.slice(0, 3).map(x => `${esc(x.name)} (${x.n})`).join(', ')}`
  : 'No pattern or color data in the product data';

// Cross-competitor insights, written from the computed numbers
const insights = [];
if (ok(sa.avgPrice) && ok(sw.avgPrice)) {
  const lower = sa.avgPrice <= sw.avgPrice ? ['Amazon', sa, 'Walmart', sw] : ['Walmart', sw, 'Amazon', sa];
  insights.push(`<li><strong>Pricing:</strong> ${lower[0]} has the lower average price (${money(lower[1].avgPrice)} vs ${money(lower[3].avgPrice)} at ${lower[2]}). Amazon ranges ${money(sa.min)} - ${money(sa.max)}; Walmart ranges ${money(sw.min)} - ${money(sw.max)}.</li>`);
}
if (ok(sa.avgRating) && ok(sw.avgRating)) {
  insights.push(`<li><strong>Ratings:</strong> Amazon averages ${sa.avgRating.toFixed(2)}/5 across ${sa.nRated} rated products; Walmart averages ${sw.avgRating.toFixed(2)}/5 across ${sw.nRated}.</li>`);
}
insights.push(`<li><strong>Variety:</strong> Amazon products show ${sa.patterns.length} distinct patterns/variants; Walmart products show ${sw.patterns.length}.</li>`);

const html = `<section class="competitor-analysis">
    <h2>Competitor Analysis</h2>

    <div class="amazon-section">
      <h3>Amazon Overview</h3>
      <div class="stats-grid">${statCards(sa, true)}
      </div>
      <div class="top-performers">
        <h4>Top Amazon Products</h4>
        <table class="data-table">
          <thead><tr><th>Product</th><th>Price</th><th>Rating</th></tr></thead>
          <tbody>${amazonRows}
          </tbody>
        </table>
        <p style="font-size:0.85rem;color:#6B7280;margin-top:0.5rem">Ranked by review-adjusted rating. Rating shows the average and review count.</p>
      </div>
      <div class="common-features">
        <h4>Common Features</h4>
        <ul>${featureItems}</ul>
      </div>
    </div>

    <div class="walmart-section">
      <h3>Walmart Overview</h3>
      <div class="stats-grid">${statCards(sw, true)}
      </div>
      <div class="top-performers">
        <h4>Top Walmart Products</h4>
        <table class="data-table">
          <thead><tr><th>Product</th><th>Price</th><th>Sizes Available</th></tr></thead>
          <tbody>${walmartRows}
          </tbody>
        </table>
        <p style="font-size:0.85rem;color:#6B7280;margin-top:0.5rem">Ranked by review-adjusted rating. Sizes are read from product names and details where present.</p>
      </div>
      <div class="variety">
        <h4>Size/Color Variety</h4>
        <ul>
          <li><strong>Sizes:</strong> ${sizesLine}</li>
          <li><strong>Colors/Patterns:</strong> ${patternsLine}</li>
        </ul>
      </div>
    </div>

    <div class="cross-comparison">
      <h3>Cross-Competitor Insights</h3>
      <ul>${insights.join('')}</ul>
    </div>
  </section>`;

return [{ json: { choices: [{ message: { content: html } }], computedStats: { amazon: { ...sa, patterns: sa.patterns.length }, walmart: { ...sw, patterns: sw.patterns.length } } } }];

// COMPARISON GENERATOR (no LLM) - drop-in replacement for the HTTP node of the same name.
// All four rows are computed from the raw product arrays; winners come from numbers, never from a model.
// Output shape matches what HTML Assembler already reads: json.choices[0].message.content
// API formats (ProductItem): price "NN.NN", rating "X.X out of 5 stars", review_count "3902"; any may be "".
// NOTE: every <br> is followed by a newline so the dashboard's tag-stripping keeps words apart.

const safe = (name, key) => { try { return $(name).first().json[key] || []; } catch (e) { return []; } };
const data = {
  wayfair: safe('Reshape Wayfair Response', 'wayfair_products'),
  amazon:  safe('Reshape Amazon Response', 'amazonProducts'),
  walmart: safe('Reshape Walmart Response', 'walmartProducts'),
};
const platforms = ['wayfair', 'amazon', 'walmart'];
const labels = { wayfair: 'Wayfair', amazon: 'Amazon', walmart: 'Walmart' };

// ---------- helpers ----------
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const parseNum = v => { const m = String(v ?? '').replace(/,/g, '').match(/\d+(?:\.\d+)?/); return m ? parseFloat(m[0]) : NaN; };
const parseRating = v => { const m = String(v ?? '').match(/(\d+(?:\.\d+)?)\s*out of\s*5/i); return m ? parseFloat(m[1]) : parseNum(v); };
const parseCount = v => { const m = String(v ?? '').replace(/,/g, '').toLowerCase().match(/(\d+(?:\.\d+)?)\s*(k)?/); return m ? Math.round(parseFloat(m[1]) * (m[2] ? 1000 : 1)) : NaN; };
const ok = Number.isFinite;
const mean = a => a.reduce((s, x) => s + x, 0) / a.length;
const money = x => ok(x) ? '$' + x.toFixed(2) : 'N/A';
const textOf = p => String(p.name ?? '').replace(/[\[\]]/g, ' ') + ' ' + (p.details || []).join(' ');

// Sizes like 5'x8', 5'3 x 7', 6'7" x 9'6", 8x10, 5 x 8 ft (best effort, from name + feature bullets)
const sizeDim = `\\d{1,2}(?:\\.\\d+)?(?:\\s*(?:ft\\.?|feet|['\u2032])\\s*(?:\\d{1,2}(?:\\.\\d+)?\\s*(?:"|in\\.?|\u2033)?)?)?`;
const sizeRe = new RegExp(`(?<![\\d.])${sizeDim}\\s*[x\u00d7]\\s*${sizeDim}(?!\\d)`, 'i');
const sizeOf = p => { const m = textOf(p).match(sizeRe); return m ? m[0].replace(/\s+/g, ' ').trim() : ''; };

const featureDefs = [
  ['Waterproof / Water Resistant', /water[\s-]?(?:proof|resistant)/i],
  ['UV / Fade Resistant', /\b(?:uv|fade)[\s-]?(?:resistant|proof|protected)|fade[\s-]?resistant/i],
  ['Stain Resistant', /stain[\s-]?(?:resistant|proof)/i],
  ['Easy to Clean', /easy[\s-]?(?:to[\s-]?)?clean|machine[\s-]?wash|hose|wipe/i],
  ['Pet Friendly', /pet[\s-]?friendly|pet[\s-]?safe/i],
  ['Non-Slip', /non[\s-]?(?:slip|skid)|slip[\s-]?resistant/i],
  ['Reversible', /reversible/i],
  ['Indoor / Outdoor Use', /indoor[\s\/&,-]*(?:and\s*)?outdoor|outdoor[\s\/&,-]*(?:and\s*)?indoor/i],
  ['Lightweight', /lightweight/i],
  ['Durable / Weather Resistant', /durab|weather[\s-]?(?:resistant|proof)/i],
];

// ---------- per-platform stats ----------
const stats = {};
for (const p of platforms) {
  const items = data[p];
  const prices = items.map(i => parseNum(i.price)).filter(x => ok(x) && x > 0);
  const ratings = items.map(i => parseRating(i.rating)).filter(x => ok(x) && x > 0 && x <= 5);
  const counts = items.map(i => parseCount(i.review_count)).filter(ok);
  const patterns = {};
  items.forEach(i => { const k = String(i.pattern || '').trim().toLowerCase(); if (k) patterns[k] = (patterns[k] || 0) + 1; });
  const featHits = featureDefs.map(([label, re]) => [label, items.filter(i => re.test(textOf(i))).length]).filter(f => f[1] > 0).sort((a, b) => b[1] - a[1]);
  const perProduct = items.map(i => featureDefs.filter(([, re]) => re.test(textOf(i))).length);
  const sizeList = items.map(sizeOf).filter(Boolean);
  stats[p] = {
    n: items.length, nPriced: prices.length, nRated: ratings.length,
    avgPrice: prices.length ? mean(prices) : NaN, minPrice: prices.length ? Math.min(...prices) : NaN, maxPrice: prices.length ? Math.max(...prices) : NaN,
    avgRating: ratings.length ? mean(ratings) : NaN, reviews: counts.reduce((s, x) => s + x, 0),
    styles: Object.keys(patterns).length,
    topStyles: Object.entries(patterns).sort((a, b) => b[1] - a[1]).slice(0, 3).map(e => e[0]),
    topFeatures: featHits.slice(0, 3), avgFeatures: items.length ? mean(perProduct) : NaN,
    sizesFound: sizeList.length,
    distinctSizes: [...new Map(sizeList.map(s => [s.toLowerCase().replace(/\s+/g, ''), s])).values()],
  };
}

// ---------- winners ----------
// fn -> number per platform; mode 'max'/'min'; positive = need at least one platform above 0 (else no data -> null)
const pick = (fn, mode, positive = false) => {
  const vals = platforms.map(p => fn(stats[p]));
  if (vals.some(v => !ok(v))) return null;
  if (positive && vals.every(v => v <= 0)) return null;
  const best = mode === 'max' ? Math.max(...vals) : Math.min(...vals);
  const w = platforms.filter((p, i) => vals[i] === best);
  return w.length === 1 ? w[0] : 'tie';
};
const win = {
  price:    pick(s => Number(s.avgPrice.toFixed(2)), 'min'),
  rating:   pick(s => Number(s.avgRating.toFixed(2)), 'max'),
  features: pick(s => Number(s.avgFeatures.toFixed(2)), 'max', true),
